.rr-win { border-top: 1px solid #e5e5e5; padding: 12px 0 8px; margin-top: 8px; }
.rr-win-head { display: flex; align-items: center; gap: 8px; }
.rr-grow { flex: 1 1 auto; }
.rr-h3 { font-size: 14px; font-weight: 700; margin: 0; }
.rr-win-summary { margin: 6px 0 2px; font-weight: 600; }
.rr-kicker { font-size: 12px; color: #5c5c5c; margin: 2px 0; }
.rr-win-form { display: flex; flex-direction: column; gap: 8px; margin-top: 8px; }
.rr-win-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(150px, 1fr)); gap: 10px; }
.rr-win-sub { font-size: 13px; font-weight: 700; margin: 6px 0 0; }
.rr-win-freeze { display: grid; grid-template-columns: 150px 150px 1fr auto; gap: 8px; align-items: end; }
.rr-win-actions { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; padding-bottom: 4px; }
.rr-win-list { margin: 4px 0; padding-left: 18px; font-size: 12.5px; }
.rr-pill { display: inline-block; font-size: 11px; font-weight: 700; padding: 2px 9px; border-radius: 10px; }
.rr-pill-ok { background: #ebf7e6; color: #2e844a; }
.rr-pill-wait { background: #fef1cd; color: #a96404; }
.rr-pill-none { background: #f3f3f3; color: #5c5c5c; }
.rr-msg { padding: 8px 10px; border-radius: 4px; font-size: 12.5px; }
.rr-msg-bad { background: #feded8; color: #8c0000; }
@media (max-width: 700px) { .rr-win-freeze { grid-template-columns: 1fr 1fr; } }
